    let vowels = 'aeiou';
    let numbers = '0123456789';
    let specials = '!@#$%^&*()_+-=[]{}|;:,.<>/?';

    let vowelArray = [];
    let consonantArray = [];
    let numberArray = [];
    let specialArray = [];

    for(let i=0; i<inputString.length; i++){
        let c = inputString.charAt(i).toLowerCase();
        if(numbers.indexOf(c)>-1) {
            numberArray.push(c);
        }
        else if(vowels.indexOf(c)>-1) {
            vowelArray.push(c);
        }
        else if(specials.indexOf(c)>-1) {
            specialArray.push(c);
        }
        else {
            consonantArray.push(c);
        }
    }

