user: Translate and explain this code to Swift
from typing import List

def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    if delimeter < 0:
        return numbers
    result = []
    for i, num in enumerate(numbers):
        result.append(num)
        if i < len(numbers) - 1:
            result.append(delimeter)
    return result

